        max-width: 600px; /* Réduction de la largeur max */
        padding: 10px; /* Réduction du padding */
    }

    .zagolovok {
        font-size: 20px; /* Taille encore plus petite pour le titre */
    }
}

@media screen and (max-width: 480px) {
    .prix {
        padding: 20px; /* Ajuste les marges pour petits écrans */
        font-size: 10px; /* Police adaptée pour mobiles */
    }

    .ramka-prix {
        max-width: 90%; /* Adapte la largeur à l'écran */
        padding: 10px; /* Maintient un petit padding */
        height: auto; /* Hauteur flexible */
    }

    .zagolovok {
        font-size: 18px; /* Taille réduite pour les petits écrans */
    }

    .prix-p {
        font-size: 12px; /* Ajuste la taille du texte */
    }
}

